  json: {
    subject: (item['Email Subject Line'] || '').trim(),
    body: (item['Email Body'] || '').trim(),
    offer: item['What are you selling or offering (optional, improves accuracy)'] || 'Not specified',
    audience: item['Target audience or persona (optional, e.g. SaaS founders, HR managers)'] || 'Not specified'
  }
}];

const item = $input.first().json;
let body = item.body;
let truncated = false;

if (body.length > 6000) {
  body = body.slice(0, 6000);
  truncated = true;
}

return [{
  json: {
    subject: item.subject,
    body: body,
    offer: item.offer,
    audience: item.audience,
    truncated
  }
}];

