const data = $input.first().json.output;

const gradeColor = (g) => {
  const map = { A: '#16a34a', B: '#65a30d', C: '#ca8a04', D: '#ea580c', F: '#dc2626' };
  return map[g] || '#6b7280';
};

const riskColor = (level) => {
  const map = { Low: '#16a34a', Medium: '#ca8a04', High: '#dc2626' };
  return map[level] || '#6b7280';
};

const scoreBar = (label, score, feedback) => `
  <div style="margin-bottom:16px;">
    <div style="display:flex;justify-content:space-between;margin-bottom:4px;">
      <span style="font-weight:600;color:#111827;font-size:14px;">${label}</span>
      <span style="font-weight:600;color:#111827;font-size:14px;">${score}/10</span>
    </div>
    <div style="background:#e5e7eb;border-radius:999px;height:8px;overflow:hidden;margin-bottom:6px;">
      <div style="background:${score >= 7 ? '#16a34a' : score >= 4 ? '#ca8a04' : '#dc2626'};height:8px;width:${score*10}%;"></div>
    </div>
    <p style="color:#6b7280;font-size:13px;margin:0;">${feedback}</p>
  </div>
`;

const fixesHtml = (data.top_fixes || []).map((f, i) => `
  <li style="margin-bottom:8px;color:#111827;font-size:14px;"><strong>${i+1}.</strong> ${f}</li>
`).join('');

const subjectsHtml = (data.rewritten_subject_lines || []).map(s => `
  <div style="background:#f3f4f6;border-radius:6px;padding:10px 14px;margin-bottom:8px;font-size:14px;color:#111827;font-family:monospace;">${s}</div>
`).join('');

const triggerWordsHtml = (data.spam_risk.trigger_words || []).length
  ? (data.spam_risk.trigger_words || []).map(w => `<span style="background:#fee2e2;color:#991b1b;padding:2px 8px;border-radius:999px;font-size:12px;margin-right:6px;display:inline-block;margin-bottom:6px;">${w}</span>`).join('')
  : '<span style="color:#16a34a;font-size:13px;">No obvious spam-trigger words found</span>';

const html = `
<!DOCTYPE html>
<html>
<head><meta charset="utf-8"><title>Cold Email Grade Report</title></head>
<body style="font-family:-apple-system,Segoe UI,Roboto,sans-serif;background:#f9fafb;margin:0;padding:32px;">
  <div style="max-width:680px;margin:0 auto;">
    <h1 style="color:#111827;font-size:22px;margin-bottom:4px;">Cold Email Grade Report</h1>
    <p style="color:#6b7280;font-size:13px;margin-top:0;">AI-generated content grade. Real deliverability also depends on domain reputation, SPF/DKIM/DMARC setup, and sending volume.</p>

    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:20px;margin:20px 0;display:flex;align-items:center;gap:20px;">
      <div style="font-size:40px;font-weight:800;color:${gradeColor(data.grade_letter)};width:70px;text-align:center;">${data.grade_letter}</div>
      <div>
        <div style="font-weight:600;color:#111827;">Overall Score: ${data.overall_score}/100</div>
        <div style="margin-top:6px;"><span style="background:${riskColor(data.spam_risk.level)};color:#fff;font-size:12px;font-weight:600;padding:3px 10px;border-radius:999px;">Spam Risk: ${data.spam_risk.level}</span></div>
      </div>
    </div>

    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:20px;margin:20px 0;">
      <div style="font-weight:600;color:#111827;margin-bottom:8px;">Spam Trigger Words</div>
      <div>${triggerWordsHtml}</div>
      <p style="color:#6b7280;font-size:13px;margin-top:8px;">${data.spam_risk.note}</p>
    </div>

    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:20px;margin:20px 0;">
      <div style="font-weight:600;color:#111827;margin-bottom:12px;">Score Breakdown</div>
      ${scoreBar('Subject Line', data.subject_line.score, data.subject_line.feedback)}
      ${scoreBar('Personalization', data.personalization.score, data.personalization.feedback)}
      ${scoreBar('Value Proposition', data.value_proposition.score, data.value_proposition.feedback)}
      ${scoreBar('Call to Action', data.cta.score, data.cta.feedback)}
      ${scoreBar('Tone', data.tone.score, data.tone.feedback)}
      <p style="color:#6b7280;font-size:13px;margin:0;"><strong>Length:</strong> ${data.length_feedback}</p>
    </div>

    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:20px;margin:20px 0;">
      <div style="font-weight:600;color:#111827;margin-bottom:10px;">Top Fixes</div>
      <ol style="padding-left:18px;margin:0;">${fixesHtml}</ol>
    </div>

    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:20px;margin:20px 0;">
      <div style="font-weight:600;color:#111827;margin-bottom:10px;">Subject Line Alternatives</div>
      ${subjectsHtml}
    </div>

    <p style="color:#9ca3af;font-size:12px;margin-top:30px;">Generated by an AI cold email grader. Content quality only - not a technical deliverability test (DNS/SPF/DKIM not checked).</p>
  </div>
</body>
</html>`;

return [{ json: { html } }];
